import{_ as a,o as t,c as o,a4 as r}from"./chunks/framework.DpieW3qv.js";const u=JSON.parse('{"title":"Glossary","description":"","frontmatter":{"title":"Glossary"},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md","lastUpdated":null}'),i={name:"glossary.md"};function s(n,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Definitions of key terms used throughout the SFCC Campaign Automation documentation.</p><p><strong>Code reference (source of truth):</strong> Actions — <code>src/config/sfcc.config.js</code> (ACTION_TYPES); normalization in <code>src/utils/helpers/action.js</code>. Asset types and zones — <code>src/config/asset.config.js</code>, <code>src/config/slots.config.js</code>. Refresh ID rules — <code>src/infrastructure/parsing/ExcelParser.js</code>. Output paths — <a href="/ocapi-docs.github.io/config/output-paths.html">Output Paths</a>, <code>src/infrastructure/filesystem/pathBuilder.js</code>.</p><p><strong>Date and time:</strong> Excel time-only values are combined with the refresh date and interpreted as <strong>UTC</strong>. The CLI displays dates and times in <strong>your computer&#39;s local time</strong>.</p><h2 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h2><h3 id="action" tabindex="-1">Action <a class="header-anchor" href="#action" aria-label="Permalink to &quot;Action&quot;">​</a></h3><p>An instruction indicating how to process a zone. Four canonical values: LAUNCH, UPDATE, REMOVE, NO_CHANGE. <strong>SKIP</strong> is accepted and treated as NO_CHANGE. Source: <code>src/config/sfcc.config.js</code> (ACTION_TYPES); normalization in <code>src/utils/helpers/action.js</code>. See <a href="/ocapi-docs.github.io/concepts/rules-and-validation.html">Rules &amp; Validation</a>.</p><p><strong>Quick mental model:</strong> LAUNCH = new content; UPDATE = change existing; REMOVE = delete from SFCC; NO_CHANGE = leave as-is; SKIP = same as NO_CHANGE.</p><table tabindex="0"><thead><tr><th>Action</th><th>Meaning</th></tr></thead><tbody><tr><td>LAUNCH</td><td>Create new content, new asset ID</td></tr><tr><td>UPDATE</td><td>Modify existing content, same ID</td></tr><tr><td>REMOVE</td><td>Delete content from SFCC</td></tr><tr><td>NO_CHANGE</td><td>Keep existing content, no processing</td></tr><tr><td>SKIP</td><td>Alias for NO_CHANGE</td></tr></tbody></table><h3 id="asset" tabindex="-1">Asset <a class="header-anchor" href="#asset" aria-label="Permalink to &quot;Asset&quot;">​</a></h3><p>See <a href="#content-asset">Content Asset</a>.</p><h3 id="asset-id" tabindex="-1">Asset ID <a class="header-anchor" href="#asset-id" aria-label="Permalink to &quot;Asset ID&quot;">​</a></h3><p>Unique identifier for a content asset in SFCC. See <a href="/ocapi-docs.github.io/concepts/rules-and-validation.html">Asset ID Rules</a>.</p><p><strong>Single-zone:</strong> <code>{brand}-{date}-{refreshId}-{assetType}</code> — e.g., <code>loft-2026-02-03-r1-pph</code></p><p><strong>Multi-zone:</strong> <code>{brand}-{date}-{refreshId}-{assetType}-{zone}</code> — e.g., <code>loft-2026-02-03-r1-homepage-hp-hero</code></p><h3 id="asset-registry" tabindex="-1">Asset Registry <a class="header-anchor" href="#asset-registry" aria-label="Permalink to &quot;Asset Registry&quot;">​</a></h3><p>JSON file tracking current asset IDs for each zone. Enables NO_CHANGE action and asset reuse. See <a href="/ocapi-docs.github.io/config/registry.html">Asset Registry</a>.</p><h3 id="asset-type" tabindex="-1">Asset Type <a class="header-anchor" href="#asset-type" aria-label="Permalink to &quot;Asset Type&quot;">​</a></h3><p>Category of promotional content (PPH, POPUP, HOMEPAGE, etc.). Source: <code>src/config/asset.config.js</code>, <code>src/config/slots/*</code>. See <a href="/ocapi-docs.github.io/config/slots.html">Slots &amp; Asset Types</a>.</p><h2 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to &quot;B&quot;">​</a></h2><h3 id="brand" tabindex="-1">Brand <a class="header-anchor" href="#brand" aria-label="Permalink to &quot;Brand&quot;">​</a></h3><p>A distinct e-commerce property. Currently: <code>loft</code> (LOFT) and <code>ann</code> (Ann Taylor).</p><h3 id="brandcontext" tabindex="-1">BrandContext <a class="header-anchor" href="#brandcontext" aria-label="Permalink to &quot;BrandContext&quot;">​</a></h3><p>Dependency injection container providing access to all services for a specific brand. The composition root of the application.</p><h3 id="build-guard" tabindex="-1">Build Guard <a class="header-anchor" href="#build-guard" aria-label="Permalink to &quot;Build Guard&quot;">​</a></h3><p>Safety check that prevents accidental overwriting of already-built or already-synced dates. Reads refresh.json sync section and ocapi-payload.json to determine state. Bypassed by the &quot;Force rebuild&quot; action in <code>make status</code>. See <a href="/ocapi-docs.github.io/cli/build.html">build</a>.</p><h3 id="business-manager" tabindex="-1">Business Manager <a class="header-anchor" href="#business-manager" aria-label="Permalink to &quot;Business Manager&quot;">​</a></h3><p>Salesforce Commerce Cloud&#39;s administrative interface for managing content, products, and site configuration.</p><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><h3 id="campaign" tabindex="-1">Campaign <a class="header-anchor" href="#campaign" aria-label="Permalink to &quot;Campaign&quot;">​</a></h3><p>Time-bound promotional entity in SFCC that coordinates when content appears on the website. Contains slot configurations and dates.</p><h3 id="campaign-id" tabindex="-1">Campaign ID <a class="header-anchor" href="#campaign-id" aria-label="Permalink to &quot;Campaign ID&quot;">​</a></h3><p>Unique identifier for a campaign. Format: <code>{brand}-{date}-{refreshId}</code>.</p><p>Example: <code>loft-2026-02-03-r1</code></p><h3 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h3><p>Command Line Interface. The primary way to interact with the automation tool. See <a href="/ocapi-docs.github.io/cli/">CLI Reference</a>.</p><h3 id="compilerefresh" tabindex="-1">CompileRefresh <a class="header-anchor" href="#compilerefresh" aria-label="Permalink to &quot;CompileRefresh&quot;">​</a></h3><p>Domain service that transforms Refresh DTOs into Campaign domain models. It has no disk I/O; the caller (e.g. GenerateDevFiles) persists the asset registry after compilation.</p><h3 id="composition" tabindex="-1">Composition <a class="header-anchor" href="#composition" aria-label="Permalink to &quot;Composition&quot;">​</a></h3><p>The process of combining multiple zone templates into a single preview file.</p><h3 id="content-asset" tabindex="-1">Content Asset <a class="header-anchor" href="#content-asset" aria-label="Permalink to &quot;Content Asset&quot;">​</a></h3><p>A self-contained HTML fragment stored in SFCC&#39;s Content Library. Content assets are the atomic units of promotional content that fill slots on web pages. They contain HTML markup and inline CSS but cannot include <code>&lt;html&gt;</code>, <code>&lt;head&gt;</code>, or <code>&lt;body&gt;</code> tags. See <a href="/ocapi-docs.github.io/concepts/content-model.html">Slots, Assets, Zones</a>.</p><h3 id="content-library" tabindex="-1">Content Library <a class="header-anchor" href="#content-library" aria-label="Permalink to &quot;Content Library&quot;">​</a></h3><p>SFCC&#39;s storage for content assets. Identified by <code>SFCC_LIBRARY_ID</code>.</p><h3 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h3><p>Scope of a slot configuration: <code>global</code> (site-wide) or <code>category</code> (category-specific).</p><h2 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h2><h3 id="data-quality-gate" tabindex="-1">Data Quality Gate <a class="header-anchor" href="#data-quality-gate" aria-label="Permalink to &quot;Data Quality Gate&quot;">​</a></h3><p>Automatic validation step in <code>make push</code> that checks for missing copy, duplicate IPIDs, unknown asset types, and other data issues before syncing to SFCC. Errors block the push; warnings prompt for confirmation. See <a href="/ocapi-docs.github.io/cli/push.html">push</a>.</p><h3 id="date-state" tabindex="-1">Date State <a class="header-anchor" href="#date-state" aria-label="Permalink to &quot;Date State&quot;">​</a></h3><p>The lifecycle state of a refresh as shown in the <code>make status</code> dashboard. The full set of states is LIVE, SYNCED, UPDATED, READY, BUILD, and NEW. See <a href="#status-states">Status States</a> for definitions and next steps. Email is auto-generated by <code>make push</code>; <code>make email</code> can regenerate it standalone. See <a href="/ocapi-docs.github.io/reference/commands.html">Command Reference</a>.</p><h3 id="dev-cli" tabindex="-1">Dev CLI <a class="header-anchor" href="#dev-cli" aria-label="Permalink to &quot;Dev CLI&quot;">​</a></h3><p>The set of commands intended for the web developer: <code>registry</code>, <code>upload</code>, <code>test</code>, <code>check</code>, <code>clean</code>, <code>docs</code>, <code>log</code>, <code>test-brands</code>. Run <code>make dev</code> to see the full list. See <a href="/ocapi-docs.github.io/reference/commands.html">Command Reference</a>.</p><h3 id="developer-mode" tabindex="-1">Developer Mode <a class="header-anchor" href="#developer-mode" aria-label="Permalink to &quot;Developer Mode&quot;">​</a></h3><p>Asset type mode where HTML is provided directly (not rendered from templates). Used for complex layouts like Homepage.</p><h3 id="dry-run" tabindex="-1">Dry Run <a class="header-anchor" href="#dry-run" aria-label="Permalink to &quot;Dry Run&quot;">​</a></h3><p>Running a command without making actual changes. Use <code>--dry-run</code> flag.</p><h3 id="dev-files" tabindex="-1">Dev Files <a class="header-anchor" href="#dev-files" aria-label="Permalink to &quot;Dev Files&quot;">​</a></h3><p>The generated output files for a refresh: HTML templates, rendered previews, asset JSON files, and the OCAPI payload. Stored in <code>dev-env/{brand}/refreshes/{date}/{refreshId}/</code>.</p><h3 id="dto" tabindex="-1">DTO <a class="header-anchor" href="#dto" aria-label="Permalink to &quot;DTO&quot;">​</a></h3><p>Data Transfer Object — a plain object for passing data between application layers without business logic. The Refresh is a DTO that carries wireframe data from the parser to the compiler.</p><h2 id="e" tabindex="-1">E <a class="header-anchor" href="#e" aria-label="Permalink to &quot;E&quot;">​</a></h2><h3 id="excel-parser" tabindex="-1">Excel Parser <a class="header-anchor" href="#excel-parser" aria-label="Permalink to &quot;Excel Parser&quot;">​</a></h3><p>Service that parses wireframe Excel files into Refresh DTOs. Supports multiple formats.</p><h2 id="g" tabindex="-1">G <a class="header-anchor" href="#g" aria-label="Permalink to &quot;G&quot;">​</a></h2><h3 id="generatedevfiles" tabindex="-1">GenerateDevFiles <a class="header-anchor" href="#generatedevfiles" aria-label="Permalink to &quot;GenerateDevFiles&quot;">​</a></h3><p>Use case that generates HTML/JSON assets and OCAPI payload from Campaign entities.</p><h2 id="h" tabindex="-1">H <a class="header-anchor" href="#h" aria-label="Permalink to &quot;H&quot;">​</a></h2><h3 id="handlebars" tabindex="-1">Handlebars <a class="header-anchor" href="#handlebars" aria-label="Permalink to &quot;Handlebars&quot;">​</a></h3><p>Template engine used for rendering HTML from templates. See <a href="/ocapi-docs.github.io/guides/templates.html">Template Authoring</a>.</p><h3 id="force-rebuild" tabindex="-1">Force Rebuild <a class="header-anchor" href="#force-rebuild" aria-label="Permalink to &quot;Force Rebuild&quot;">​</a></h3><p>Workflow for regenerating HTML after template changes or fixes. Use the &quot;Force rebuild&quot; action in <code>make status</code> to bypass the build guard and regenerate all assets, then <code>make push FORCE=1</code> to re-sync. See <a href="/ocapi-docs.github.io/excel/best-practices.html">best practices</a>.</p><h2 id="l" tabindex="-1">L <a class="header-anchor" href="#l" aria-label="Permalink to &quot;L&quot;">​</a></h2><h3 id="launch" tabindex="-1">LAUNCH <a class="header-anchor" href="#launch" aria-label="Permalink to &quot;LAUNCH&quot;">​</a></h3><p>Action indicating new content creation. Generates new asset ID and registers in registry.</p><h2 id="n" tabindex="-1">N <a class="header-anchor" href="#n" aria-label="Permalink to &quot;N&quot;">​</a></h2><h3 id="no-change" tabindex="-1">NO_CHANGE <a class="header-anchor" href="#no-change" aria-label="Permalink to &quot;NO_CHANGE&quot;">​</a></h3><p>Action indicating content is unchanged from the previous refresh. Reuses the existing asset ID from the registry without regenerating HTML or syncing to SFCC. This is the most common action in wireframes. See <a href="/ocapi-docs.github.io/concepts/rules-and-validation.html">Rules &amp; Validation</a>.</p><h2 id="o" tabindex="-1">O <a class="header-anchor" href="#o" aria-label="Permalink to &quot;O&quot;">​</a></h2><h3 id="ocapi" tabindex="-1">OCAPI <a class="header-anchor" href="#ocapi" aria-label="Permalink to &quot;OCAPI&quot;">​</a></h3><p>Open Commerce API — Salesforce Commerce Cloud&#39;s REST API for managing content, campaigns, and slots programmatically. See <a href="/ocapi-docs.github.io/concepts/ocapi-readiness.html">OCAPI Readiness</a>.</p><h3 id="ocapi-payload" tabindex="-1">OCAPI Payload <a class="header-anchor" href="#ocapi-payload" aria-label="Permalink to &quot;OCAPI Payload&quot;">​</a></h3><p>JSON file (<code>ocapi-payload.json</code>) containing the complete campaign data formatted for SFCC API submission: campaign metadata, content assets (with HTML body), slot configurations, and slot bindings.</p><h2 id="p" tabindex="-1">P <a class="header-anchor" href="#p" aria-label="Permalink to &quot;P&quot;">​</a></h2><h3 id="pod" tabindex="-1">POD <a class="header-anchor" href="#pod" aria-label="Permalink to &quot;POD&quot;">​</a></h3><p>Production instance in SFCC. Content is replicated from staging to PODs.</p><h3 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h3><p>Composed view of multi-zone assets for visual verification before sync.</p><h3 id="producer-cli" tabindex="-1">Producer CLI <a class="header-anchor" href="#producer-cli" aria-label="Permalink to &quot;Producer CLI&quot;">​</a></h3><p>The producer make targets: <code>pull</code>, <code>preview</code>, <code>push</code>, <code>replicate</code>, <code>email</code>, <code>commit</code>, <code>status</code>, <code>browse</code>; plus <code>setup</code>, <code>health</code>. Building happens automatically via <code>make pull</code> and <code>make preview</code>. Force-rebuild after template edits: use &quot;Force rebuild&quot; in <code>make status</code>. Note: <code>make push</code> auto-generates the email. See <a href="/ocapi-docs.github.io/reference/commands.html">Command Reference</a>.</p><h3 id="pull" tabindex="-1">Pull <a class="header-anchor" href="#pull" aria-label="Permalink to &quot;Pull&quot;">​</a></h3><p><code>make pull</code> — the daily starting command. Combines git sync, data fetch, status dashboard, and date selection into one step. See <a href="/ocapi-docs.github.io/cli/pull.html">pull</a>.</p><h2 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h2><h3 id="refresh" tabindex="-1">Refresh <a class="header-anchor" href="#refresh" aria-label="Permalink to &quot;Refresh&quot;">​</a></h3><p>A data transfer object (DTO) containing wireframe data for a specific date. Holds all asset types, zones, and items parsed from the Excel/Smartsheet source. The input to the generation process. See <a href="/ocapi-docs.github.io/concepts/rules-and-validation.html">Rules &amp; Validation</a> and <a href="/ocapi-docs.github.io/concepts/content-model.html">Content Model</a>.</p><h3 id="refresh-bundle" tabindex="-1">Refresh Bundle <a class="header-anchor" href="#refresh-bundle" aria-label="Permalink to &quot;Refresh Bundle&quot;">​</a></h3><p>A conceptual collection of all refreshes for a single date (r1, r2, r3, etc.). Each refresh is stored in its own directory under <code>dev-env/{brand}/refreshes/{date}/{refreshId}/</code>; there is no single <code>refresh-bundle.json</code> file.</p><h3 id="refresh-id" tabindex="-1">Refresh ID <a class="header-anchor" href="#refresh-id" aria-label="Permalink to &quot;Refresh ID&quot;">​</a></h3><p>Ordinal identifier for multiple refreshes on the same date: r1, r2, r3, etc. Assigned by start time order. Source: <code>src/infrastructure/parsing/ExcelParser.js</code> (_assignRefreshIds).</p><h3 id="registry" tabindex="-1">Registry <a class="header-anchor" href="#registry" aria-label="Permalink to &quot;Registry&quot;">​</a></h3><p>See <a href="#asset-registry">Asset Registry</a>.</p><h3 id="replication" tabindex="-1">Replication <a class="header-anchor" href="#replication" aria-label="Permalink to &quot;Replication&quot;">​</a></h3><p>Process of copying content from staging to production PODs. Currently requires manual trigger in Business Manager.</p><h3 id="remove" tabindex="-1">REMOVE <a class="header-anchor" href="#remove" aria-label="Permalink to &quot;REMOVE&quot;">​</a></h3><p>Action indicating content should be deleted from SFCC and unregistered.</p><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><h3 id="sfcc" tabindex="-1">SFCC <a class="header-anchor" href="#sfcc" aria-label="Permalink to &quot;SFCC&quot;">​</a></h3><p>Salesforce Commerce Cloud. The e-commerce platform this tool integrates with.</p><h3 id="site-id" tabindex="-1">Site ID <a class="header-anchor" href="#site-id" aria-label="Permalink to &quot;Site ID&quot;">​</a></h3><p>SFCC identifier for the website. Set via <code>SFCC_SITE_ID</code> environment variable.</p><h3 id="slot" tabindex="-1">Slot <a class="header-anchor" href="#slot" aria-label="Permalink to &quot;Slot&quot;">​</a></h3><p>A designated area on an SFCC page where content can be displayed. Slots are filled by slot configurations.</p><h3 id="slotconfiguration" tabindex="-1">SlotConfiguration <a class="header-anchor" href="#slotconfiguration" aria-label="Permalink to &quot;SlotConfiguration&quot;">​</a></h3><p>Domain entity linking a ContentAsset to a specific slot within a Campaign. Defines when, where, and what content appears.</p><h3 id="slot-id" tabindex="-1">Slot ID <a class="header-anchor" href="#slot-id" aria-label="Permalink to &quot;Slot ID&quot;">​</a></h3><p>Unique identifier for a slot in SFCC. Examples: <code>global-promotion-banner</code>, <code>hp-top-banner</code>.</p><h3 id="smartsheet" tabindex="-1">Smartsheet <a class="header-anchor" href="#smartsheet" aria-label="Permalink to &quot;Smartsheet&quot;">​</a></h3><p>Cloud-based spreadsheet application used as a wireframe data source.</p><h3 id="status-states" tabindex="-1">Status States <a class="header-anchor" href="#status-states" aria-label="Permalink to &quot;Status States&quot;">​</a></h3><p>States shown in the <code>make status</code> dashboard. At most one refresh is LIVE (the one on the homepage right now). Source: status state labels in <code>src/cli/prompts/</code> (datePicker stateLabel / stateIcon); sync state from refresh.json sync section. <strong>STALE</strong> is the internal state for &quot;source changed since last sync&quot;; the UI displays it as <strong>UPDATED</strong>.</p><table tabindex="0"><thead><tr><th>State</th><th>Condition</th><th>Next Step</th></tr></thead><tbody><tr><td><strong>LIVE</strong></td><td>Synced and on site now: folder date is today, or current time is inside the refresh&#39;s start–end window (folder = nominal start; end shows span). Only one row is LIVE.</td><td>done (or shows go-live date)</td></tr><tr><td><strong>SYNCED</strong></td><td>Synced but not currently live (outside window and/or date not today)</td><td>done (or shows go-live date)</td></tr><tr><td><strong>UPDATED</strong></td><td>(Display label for <strong>STALE</strong>.) Previously synced but source data changed since last sync (needs rebuild)</td><td><code>make preview</code></td></tr><tr><td><strong>READY</strong></td><td><code>ocapi-payload.json</code> exists, not yet pushed</td><td><code>make push</code></td></tr><tr><td><strong>BUILD</strong></td><td><code>refresh.json</code> exists but no payload</td><td><code>make preview</code> (auto-builds)</td></tr><tr><td><strong>NEW</strong></td><td>Data fetched, not yet built (same as BUILD)</td><td><code>make preview</code> (auto-builds)</td></tr></tbody></table><p>See <a href="/ocapi-docs.github.io/cli/status.html">status</a> for details.</p><h3 id="staging" tabindex="-1">Staging <a class="header-anchor" href="#staging" aria-label="Permalink to &quot;Staging&quot;">​</a></h3><p>SFCC environment for testing content before production. Content syncs here first.</p><h3 id="sticky-selection-active-refresh" tabindex="-1">Sticky Selection (active refresh) <a class="header-anchor" href="#sticky-selection-active-refresh" aria-label="Permalink to &quot;Sticky Selection (active refresh)&quot;">​</a></h3><p>The currently selected refresh (<code>date/r#</code>), stored in <code>dev-env/.ocapi-config.json</code> under <code>brandState.{brand}.currentDate</code> (gitignored). The config file is created on first use if missing, with currentDate set to today for the active brand. Set by <code>make status</code> or <code>make pull</code>. Used by <code>make preview</code>, <code>make push</code>, <code>make email</code>, etc. See <a href="/ocapi-docs.github.io/cli/status.html">status</a>.</p><h3 id="sync" tabindex="-1">Sync <a class="header-anchor" href="#sync" aria-label="Permalink to &quot;Sync&quot;">​</a></h3><p>Process of pushing campaign data to SFCC via OCAPI. Now accessed via <code>make push</code>, which adds automatic data quality validation. See <a href="/ocapi-docs.github.io/cli/push.html">push</a>.</p><h2 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h2><h3 id="template" tabindex="-1">Template <a class="header-anchor" href="#template" aria-label="Permalink to &quot;Template&quot;">​</a></h3><p>Handlebars file used to generate HTML content. Located in <code>templates/</code> directory.</p><h3 id="template-mode" tabindex="-1">Template Mode <a class="header-anchor" href="#template-mode" aria-label="Permalink to &quot;Template Mode&quot;">​</a></h3><p>Asset type mode where HTML is rendered from Handlebars templates using zone data.</p><h3 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h3><p>Shared type definitions (SyncResult, RefreshDTO, OCAPI shapes) live in <code>src/types.d.ts</code>. JSDoc references them via <code>src/types.js</code> for <code>@param</code> and <code>@returns</code> annotations.</p><h2 id="u" tabindex="-1">U <a class="header-anchor" href="#u" aria-label="Permalink to &quot;U&quot;">​</a></h2><h3 id="update" tabindex="-1">UPDATE <a class="header-anchor" href="#update" aria-label="Permalink to &quot;UPDATE&quot;">​</a></h3><p>Action indicating modification to existing content. Reuses existing asset ID from registry.</p><h3 id="upload" tabindex="-1">Upload <a class="header-anchor" href="#upload" aria-label="Permalink to &quot;Upload&quot;">​</a></h3><p>Process of pushing only content assets (not campaign/slots) to SFCC. See <a href="/ocapi-docs.github.io/cli/upload.html">CLI: upload</a>.</p><h3 id="use-case" tabindex="-1">Use Case <a class="header-anchor" href="#use-case" aria-label="Permalink to &quot;Use Case&quot;">​</a></h3><p>Application layer class that orchestrates domain operations. Examples: GenerateDevFiles, SyncToSfcc, ParseExcel.</p><h2 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V&quot;">​</a></h2><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><p>Process of checking templates and refresh data for SFCC compatibility. Runs automatically as part of <code>make push</code>. See <a href="/ocapi-docs.github.io/concepts/rules-and-validation.html">Validation Rules</a>.</p><h3 id="vitepress" tabindex="-1">VitePress <a class="header-anchor" href="#vitepress" aria-label="Permalink to &quot;VitePress&quot;">​</a></h3><p>Static site generator used for this documentation.</p><h2 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W&quot;">​</a></h2><h3 id="wireframe" tabindex="-1">Wireframe <a class="header-anchor" href="#wireframe" aria-label="Permalink to &quot;Wireframe&quot;">​</a></h3><p>Excel or Smartsheet document containing campaign content data — the source input for the automation. Wireframes specify what promotional content goes live on which dates, including copy, links, actions (LAUNCH/UPDATE/REMOVE), and zone assignments. Also referred to as &quot;the Excel file&quot; or &quot;the spreadsheet.&quot;</p><h2 id="z" tabindex="-1">Z <a class="header-anchor" href="#z" aria-label="Permalink to &quot;Z&quot;">​</a></h2><h3 id="zone" tabindex="-1">Zone <a class="header-anchor" href="#zone" aria-label="Permalink to &quot;Zone&quot;">​</a></h3><p>A specific content area within an asset type. Multi-zone asset types (like Homepage) have many zones. See <a href="/ocapi-docs.github.io/concepts/content-model.html">Slots, Assets, Zones</a>.</p><h3 id="zone-key" tabindex="-1">Zone Key <a class="header-anchor" href="#zone-key" aria-label="Permalink to &quot;Zone Key&quot;">​</a></h3><p>Identifier for a zone within an asset type. Examples: <code>HP_TOP_BANNER</code>, <code>HP_HERO</code>, <code>MAIN</code>.</p>',155)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
